#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1e9 + 7;

ll modpow(ll a, ll b, ll mod = MOD) {
    ll res = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return res;
}

ll inv(ll x) {
    return modpow(x, MOD - 2, MOD);
}

vector<pair<ll, ll>> factorize(ll n) {
    vector<pair<ll, ll>> factors;
    for (ll i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            ll cnt = 0;
            while (n % i == 0) {
                n /= i;
                cnt++;
            }
            factors.emplace_back(i, cnt);
        }
    }
    if (n > 1) factors.emplace_back(n, 1);
    return factors;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, k;
    cin >> n >> k;

    auto factors = factorize(n);

    ll result = 1;

    for (auto &[p, e] : factors) {
        // dp[a] = probability of being at exponent a after current steps
        vector<ll> dp(e + 1, 0);
        dp[e] = 1;

        for (ll step = 0; step < k; ++step) {
            vector<ll> new_dp(e + 1, 0);
            for (ll a = 0; a <= e; ++a) {
                if (dp[a] == 0) continue;
                ll prob = dp[a] * inv(a + 1) % MOD;
                for (ll b = 0; b <= a; ++b) {
                    new_dp[b] = (new_dp[b] + prob) % MOD;
                }
            }
            dp = new_dp;
        }

        // Compute expected value contribution: sum(dp[a] * p^a)
        ll contrib = 0;
        ll pow_p = 1; // p^0
        for (ll a = 0; a <= e; ++a) {
            contrib = (contrib + dp[a] * pow_p) % MOD;
            pow_p = pow_p * p % MOD;
        }

        result = result * contrib % MOD;
    }

    cout << result << endl;

    return 0;
}
